:root {
    --bg-color: #f8f9fa;
    --text-color: #212529;
    --header-bg: #ffffff;
    --card-bg: #ffffff;
    --card-border: #e3e6f0;
    --primary-color: #ff5722;
    --primary-hover: #f4511e;
    --nav-text: #495057;
    --shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}

body.dark-mode {
    --bg-color: #121212;
    --text-color: #e0e0e0;
    --header-bg: #1e1e1e;
    --card-bg: #1e1e1e;
    --card-border: #333333;
    --primary-color: #ff7043;
    --primary-hover: #ff5722;
    --nav-text: #b0bec5;
    --shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    line-height: 1.6;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.header {
    background-color: var(--header-bg);
    box-shadow: var(--shadow);
    position: sticky;
    top: 0;
    z-index: 1000;
    transition: background-color 0.3s ease;
}

.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 70px;
}

.logo h1 {
    font-size: 1.5rem;
    color: var(--primary-color);
}

.nav {
    display: flex;
    align-items: center;
    gap: 20px;
}

.nav a {
    text-decoration: none;
    color: var(--nav-text);
    font-weight: 500;
    transition: color 0.2s;
}

.nav a:hover,
.nav a.active {
    color: var(--primary-color);
}

.dark-mode-toggle {
    background: none;
    border: 2px solid var(--card-border);
    border-radius: 50%;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: var(--text-color);
    font-size: 1.1rem;
    transition: all 0.2s ease;
}

.dark-mode-toggle:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.main-container {
    max-width: 1200px;
    margin: 30px auto;
    padding: 0 20px;
}

.hero {
    text-align: center;
    padding: 40px 20px;
    margin-bottom: 30px;
}

.hero h2 {
    font-size: 2.2rem;
    margin-bottom: 15px;
    color: var(--text-color);
}

.hero p {
    color: var(--nav-text);
    max-width: 700px;
    margin: 0 auto;
}

.section {
    margin-bottom: 40px;
}

.section h3 {
    font-size: 1.5rem;
    margin-bottom: 20px;
    border-left: 4px solid var(--primary-color);
    padding-left: 10px;
}

.cards-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
}

.card {
    background-color: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    padding: 20px;
    box-shadow: var(--shadow);
    transition: background-color 0.3s ease, border-color 0.3s ease;
}

.card h4 {
    margin-bottom: 15px;
    font-size: 1.2rem;
    color: var(--primary-color);
}

.card p {
    margin-bottom: 8px;
    color: var(--text-color);
}

.btn-copy,
.btn-primary {
    background-color: var(--primary-color);
    color: #ffffff;
    border: none;
    padding: 10px 16px;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    margin-top: 10px;
    transition: background-color 0.2s;
    min-height: 44px;
    min-width: 44px;
}

.btn-copy:hover,
.btn-primary:hover {
    background-color: var(--primary-hover);
}

.generator-box {
    background-color: var(--card-bg);
    border: 1px solid var(--card-border);
    padding: 25px;
    border-radius: 8px;
    box-shadow: var(--shadow);
}

.generator-box label {
    display: block;
    margin-bottom: 10px;
    font-weight: 500;
}

.generator-box select {
    width: 100%;
    padding: 12px;
    border-radius: 6px;
    border: 1px solid var(--card-border);
    background-color: var(--bg-color);
    color: var(--text-color);
    margin-bottom: 15px;
    min-height: 44px;
}

.result-area {
    margin-top: 20px;
    font-weight: 500;
}

.footer {
    background-color: var(--header-bg);
    text-align: center;
    padding: 20px 0;
    margin-top: 50px;
    border-top: 1px solid var(--card-border);
    color: var(--nav-text);
}

@media (max-width: 768px) {
    .nav-container {
        flex-direction: column;
        height: auto;
        padding: 15px 0;
    }
    .nav {
        margin-top: 15px;
        gap: 15px;
        flex-wrap: wrap;
        justify-content: center;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const darkModeToggle = document.getElementById('darkModeToggle');
    const body = document.body;
    const icon = darkModeToggle ? darkModeToggle.querySelector('i') : null;

    const updateIcon = (isDark) => {
        if (!icon) return;
        if (isDark) {
            icon.className = 'fa-solid fa-sun';
        } else {
            icon.className = 'fa-solid fa-moon';
        }
    };

    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
        body.classList.add('dark-mode');
        updateIcon(true);
    } else {
        updateIcon(false);
    }

    if (darkModeToggle) {
        darkModeToggle.addEventListener('click', () => {
            body.classList.toggle('dark-mode');
            const isDark = body.classList.contains('dark-mode');
            localStorage.setItem('theme', isDark ? 'dark' : 'light');
            updateIcon(isDark);
        });
    }

    const generateBtn = document.getElementById('generateBtn');
    if (generateBtn) {
        generateBtn.addEventListener('click', () => {
            const deviceType = document.getElementById('deviceType').value;
            const resultArea = document.getElementById('resultArea');
            let sensitivityText = '';

            if (deviceType === 'ios') {
                sensitivityText = 'Gợi ý iPhone: General: 97 | Red Dot: 94 | 2x Scope: 90 | DPI: Mặc định';
            } else if (deviceType === 'gaming') {
                sensitivityText = 'Gợi ý Gaming Phone: General: 99 | Red Dot: 96 | 2x Scope: 95 | DPI: 600';
            } else {
                sensitivityText = 'Gợi ý Android: General: 92 | Red Dot: 88 | 2x Scope: 85 | DPI: 500';
            }

            resultArea.innerHTML = `<div style="padding: 15px; background: var(--bg-color); border: 1px solid var(--card-border); border-radius: 6px;">${sensitivityText}</div>`;
        });
    }
});
